    paris_g11: { id: "paris_g11", name: "Alix Girard", category: "Guides", guide: true, city: "Paris", pic: "alix-girard", gender: "Others", rating: "3.7", reviews: "410", kind: "Local guide", walk: "meets in Paris", open: "Available this week", note: "Alix is a Paris local who loves showing visitors the version of the city they actually lives in. Warm, easy-going and full of stories, Alix runs architecture tours that go well beyond the guidebook.", detail: "Born and raised around Paris, Alix has spent years getting to know its streets, its people and its best kept corners. Tours are relaxed and personal, and they happily shapes the day around whatever you're curious about, whether that's architecture and design, food, history or just finding the perfect quiet spot for a coffee. Their care goes into how you feel at the end of the day rather than ticking off a checklist, so you come away feeling like you saw the real Paris, not just its postcards." },
